extends Node

@export var seed_val: int = 12345
@export var width: int = 64
@export var height: int = 64
@export var wall_threshold: float = 0.0

var _rooms: Array[Rect2i] = []

func _ready():
    pass

func generate(target: TileMapLayer) -> void:
    target.clear()
    _rooms.clear()

    var noise = FastNoiseLite.new()
    noise.seed = seed_val

    # Initialize walls
    for x in range(width):
        for y in range(height):
            if x == 0 or x == width - 1 or y == 0 or y == height - 1:
                target.set_cell(Vector2i(x, y), 1, Vector2i(0, 0))
            else:
                var n = noise.get_noise_2d(x, y)
                if n < wall_threshold:
                    target.set_cell(Vector2i(x, y), 1, Vector2i(0, 0))
                else:
                    target.set_cell(Vector2i(x, y), 0, Vector2i(0, 0))

    # Carve rooms
    var rng = RandomNumberGenerator.new()
    rng.seed = seed_val

    var attempts = 0
    while _rooms.size() < 3 and attempts < 100:
        attempts += 1
        var w = rng.randi_range(4, 8)
        var h = rng.randi_range(4, 8)
        var x = rng.randi_range(1, width - w - 1)
        var y = rng.randi_range(1, height - h - 1)
        var rect = Rect2i(x, y, w, h)

        var collision = false
        for r in _rooms:
            if rect.intersects(r):
                collision = true
                break

        if not collision:
            _rooms.append(rect)
            for rx in range(rect.position.x, rect.end.x):
                for ry in range(rect.position.y, rect.end.y):
                    target.set_cell(Vector2i(rx, ry), 0, Vector2i(0, 0))

    # Carve corridors (connecting consecutive rooms)
    for i in range(_rooms.size() - 1):
        var start_room = _rooms[i]
        var end_room = _rooms[i+1]
        var start_pos = Vector2i(start_room.position.x + start_room.size.x / 2, start_room.position.y + start_room.size.y / 2)
        var end_pos = Vector2i(end_room.position.x + end_room.size.x / 2, end_room.position.y + end_room.size.y / 2)

        # Horizontal then vertical
        for x in range(min(start_pos.x, end_pos.x), max(start_pos.x, end_pos.x) + 1):
            target.set_cell(Vector2i(x, start_pos.y), 0, Vector2i(0, 0))
        for y in range(min(start_pos.y, end_pos.y), max(start_pos.y, end_pos.y) + 1):
            target.set_cell(Vector2i(end_pos.x, y), 0, Vector2i(0, 0))

func count_floor_tiles(target: TileMapLayer) -> int:
    var count = 0
    for x in range(width):
        for y in range(height):
            if target.get_cell_source_id(Vector2i(x, y)) == 0:
                count += 1
    return count

func find_rooms() -> Array[Rect2i]:
    return _rooms
EOF

